//! The channel vector files of design §5.2 rule (4) and §12.2 (`protocol/test-vectors/ch_*.txt`),
//! generated by this crate and replayed by an independent implementation written from the design
//! text (`client-core/mls-kat/tests/spec_replay.rs`; the JDK replay is slice S2b).
//!
//! `GHOST_WRITE_VECTORS=1 cargo test -p ghost-client-mls --test vectors` rewrites the files; without
//! it the test regenerates every value and compares the files byte for byte. The values that need
//! MLS randomness (a canonical KeyPackage, an application message) are **samples**: made once in
//! write mode, read back in compare mode, and re-checked here (a KeyPackage is still canonical and
//! 395 bytes; every value derived from a sample is recomputed).

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::PathBuf;

use ed25519_dalek::SigningKey;
use ghost_client_mls::canonical;
use ghost_client_mls::codec::base32_lower;
use ghost_client_mls::content::{Body, ChannelContent, InviteIssued};
use ghost_client_mls::derive::*;
use ghost_client_mls::ext::{
    AdmitEvidence, Bootstrap, ChannelContext, ChannelOrder, CommitAad, GhostLeaf, KpBind, Purpose,
    SwapEvidence,
};
use ghost_client_mls::group::{ChannelHandle, MlsContext};
use ghost_client_mls::invite::{self, InviteFields};
use ghost_client_mls::join::{self, JoinAuth, JoinRequest, RequestType, WelcomeBlob};
use ghost_client_mls::seal::{self, Order, SealKeyInput};
use sha2::{Digest, Sha256};

fn dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../protocol/test-vectors")
}

fn writing() -> bool {
    std::env::var("GHOST_WRITE_VECTORS").is_ok_and(|v| v == "1")
}

/// The committed file parsed as `section -> key -> value` (compare mode's source of samples).
fn committed(name: &str) -> BTreeMap<String, BTreeMap<String, String>> {
    let mut out: BTreeMap<String, BTreeMap<String, String>> = BTreeMap::new();
    let Ok(text) = std::fs::read_to_string(dir().join(name)) else {
        return out;
    };
    let mut section = String::new();
    for line in text.lines() {
        if line.starts_with('#') || line.trim().is_empty() {
            continue;
        }
        if let Some(s) = line.strip_prefix('[').and_then(|l| l.strip_suffix(']')) {
            section = s.to_string();
        } else if let Some((k, v)) = line.split_once(" = ") {
            out.entry(section.clone())
                .or_default()
                .insert(k.to_string(), v.to_string());
        }
    }
    out
}

struct Out {
    name: &'static str,
    text: String,
}

impl Out {
    fn new(name: &'static str, header: &str) -> Self {
        let mut text = String::new();
        for l in header.lines() {
            if l.is_empty() {
                let _ = writeln!(text, "#");
            } else {
                let _ = writeln!(text, "# {l}");
            }
        }
        Self { name, text }
    }
    fn section(&mut self, s: &str) {
        let _ = writeln!(self.text, "\n[{s}]");
    }
    fn kv(&mut self, k: &str, v: impl AsRef<str>) {
        let _ = writeln!(self.text, "{k} = {}", v.as_ref());
    }
    /// Lower-case hex; `-` for an empty value (no trailing whitespace in the files).
    fn hex(&mut self, k: &str, v: &[u8]) {
        if v.is_empty() {
            self.kv(k, "-");
        } else {
            self.kv(k, hex::encode(v));
        }
    }
    fn finish(self) {
        let path = dir().join(self.name);
        if writing() {
            std::fs::write(&path, &self.text).unwrap();
        } else {
            let old = std::fs::read_to_string(&path)
                .unwrap_or_else(|_| panic!("{} missing: GHOST_WRITE_VECTORS=1", path.display()));
            assert!(
                old == self.text,
                "{} differs from what the crate generates (GHOST_WRITE_VECTORS=1 rewrites it; review the diff)",
                self.name
            );
        }
    }
}

fn b32(label: &str) -> [u8; 32] {
    Sha256::digest(label.as_bytes()).into()
}

fn b16(label: &str) -> [u8; 16] {
    let mut o = [0u8; 16];
    o.copy_from_slice(&b32(label)[..16]);
    o
}

#[test]
fn ch_derive() {
    let mut o = Out::new(
        "ch_derive.txt",
        "GHOST channel derivations (Phase 10 design faza10-forum.md §5.2, corrected by §19.27 TR-6 and §19.28.3;\n\
         the invite seal as corrected by §19.29.3). Generated and checked by\n\
         client-core/mls/tests/vectors.rs::ch_derive; replayed independently by\n\
         client-core/mls-kat/tests/spec_replay.rs (and by the JDK in slice S2b).\n\
         \n\
         hkdf(ikm, salt, info) = HKDF-SHA256(ikm, salt, info, L = 32); '-' is the empty salt.\n\
         Inputs are SHA-256 of a label so the file regenerates exactly. K_ep and G come from MLS\n\
         exporters (labels ghost/v1/ch/epoch and ghost/v1/ch/generation, context = channel_id, L = 32);\n\
         the file starts from their values.",
    );
    let k_ep = EpochExport::from_bytes(b32("vector k_ep"));
    o.section("epoch");
    o.kv("exporter_label", "ghost/v1/ch/epoch");
    o.hex("k_ep", k_ep.as_bytes());
    o.hex("r_ep", derive_epoch_recognition(&k_ep).as_bytes());

    let g = GenerationSecret::from_bytes(b32("vector G"));
    let jk = derive_join_key(&g);
    let (rb, db) = (derive_read_base(&g), derive_deposit_base(&g));
    let ns = derive_namespace(&g);
    o.section("generation");
    o.kv("exporter_label", "ghost/v1/ch/generation");
    o.hex("g", g.as_bytes());
    o.hex("ns", &ns);
    o.hex("read_base", rb.as_bytes());
    o.hex("deposit_base", db.as_bytes());
    o.hex("join_key", jk.as_bytes());
    o.hex("r_join", derive_join_recognition(&jk).as_bytes());
    for s in [0u8, 7] {
        let rs = derive_read_secret(&rb, s);
        let ds = derive_deposit_secret(&db, s);
        o.hex(&format!("read_secret_slot_{s}"), &rs);
        o.hex(&format!("deposit_secret_slot_{s}"), &ds);
        o.hex(
            &format!("read_credential_slot_{s}"),
            &credential_v3(CredentialKind::Read, s, &ns, &rs),
        );
        o.hex(
            &format!("read_verifier_slot_{s}"),
            &credential_verifier(CredentialKind::Read, s, &ns, &rs),
        );
        o.hex(
            &format!("deposit_credential_slot_{s}"),
            &credential_v3(CredentialKind::Deposit, s, &ns, &ds),
        );
        o.hex(
            &format!("deposit_verifier_slot_{s}"),
            &credential_verifier(CredentialKind::Deposit, s, &ns, &ds),
        );
    }

    let salt = b16("vector seal salt");
    o.section("seal_keys");
    o.hex("salt", &salt);
    o.hex("ns", &ns);
    o.hex(
        "epoch_seal_key",
        derive_epoch_seal_key(&k_ep, &salt, &ns).as_bytes(),
    );
    o.hex(
        "join_seal_key",
        derive_join_seal_key(&jk, &salt, &ns).as_bytes(),
    );

    let ps = PseudonymSeed::from_bytes(b32("vector pseudonym seed"));
    o.section("pseudonym");
    o.hex("pseudonym_seed", ps.as_bytes());
    o.hex(
        "pseudonym_key",
        &ghost_client_mls::provider::PseudonymSigner::from_seed(&ps).public(),
    );

    let seed = InviteSeed::from_bytes(b32("vector invite seed"));
    o.section("invite_key");
    o.hex("invite_seed", seed.as_bytes());
    o.hex(
        "invite_pk",
        &derive_invite_signing_key(&seed).verifying_key().to_bytes(),
    );

    let ch = b32("vector channel");
    let cs: Vec<[u8; 32]> = (0..3)
        .map(|i| b32(&format!("vector committer {i}")))
        .collect();
    o.section("committers");
    o.hex("channel_id", &ch);
    o.kv(
        "committers",
        cs.iter().map(hex::encode).collect::<Vec<_>>().join(","),
    );
    o.hex("digest", &committers_digest(&ch, &cs).unwrap());
    let mut rev = cs.clone();
    rev.reverse();
    o.hex("digest_reordered", &committers_digest(&ch, &rev).unwrap());
    o.hex(
        "digest_first_two",
        &committers_digest(&ch, &cs[..2]).unwrap(),
    );

    let isalt = b16("vector invite salt");
    let pw = InvitePassword::from_bytes(b"cabin frost ladder margin orbit".to_vec());
    let ikm = derive_invite_password_key(&pw, &isalt, 1).unwrap();
    o.section("invite_seal");
    o.hex("salt", &isalt);
    o.hex(
        "open_seal_key",
        derive_open_invite_seal_key(&OpenInviteSalt::from_bytes(isalt)).as_bytes(),
    );
    o.hex("password_nfkd_utf8", pw.as_bytes());
    o.kv("kdf_code_1_profile", "argon2id m=65536 t=1 p=4 T=32 v=0x13");
    o.hex("argon2id_ikm", ikm.as_bytes());
    o.hex(
        "password_seal_key",
        derive_invite_seal_key(&ikm, &isalt, 1).as_bytes(),
    );

    o.section("argon2id_rfc9106_5_3");
    o.kv("parameters", "argon2id m=32 t=3 p=4 T=32 v=0x13");
    o.hex("password", &[1u8; 32]);
    o.hex("salt", &[2u8; 16]);
    o.hex("secret", &[3u8; 8]);
    o.hex("associated_data", &[4u8; 12]);
    o.kv(
        "tag",
        "0d640df58d78766c08c037a34a8b53c9d01ef0452d75b65eb52520e96b01e659",
    );
    o.finish();
}

#[test]
fn ch_seal() {
    let mut o = Out::new(
        "ch_seal.txt",
        "GHOST channel outer seal (design §5.6, §5.7). Generated and checked by\n\
         client-core/mls/tests/vectors.rs::ch_seal; replayed by client-core/mls-kat/tests/spec_replay.rs.\n\
         blob = salt || hint || ChaCha20-Poly1305(k, 0^12, AD, P); a blob is given in full for 4096 and by\n\
         SHA-256 above. Mutations name what the replayer changes: flip_byte_<i> (xor 1 at i), truncate_1,\n\
         other_ns (open with ns xor 0x01 at byte 0), other_mode. Each must fail to open.",
    );
    let k_ep = EpochExport::from_bytes(b32("vector k_ep"));
    let g = GenerationSecret::from_bytes(b32("vector G"));
    let jk = derive_join_key(&g);
    let ns = derive_namespace(&g);
    let body = b"a channel blob body".to_vec();
    for (mode, key) in [
        (seal::MODE_JOIN, SealKeyInput::Join(&jk)),
        (seal::MODE_WELCOME, SealKeyInput::Join(&jk)),
        (seal::MODE_EPOCH, SealKeyInput::Epoch(&k_ep)),
    ] {
        for bucket in seal::BUCKETS {
            let salt = b16(&format!("seal salt {mode} {bucket}"));
            let order = if mode == seal::MODE_EPOCH {
                Order {
                    epoch: 7,
                    sender_leaf: 3,
                    seq: 12,
                }
            } else {
                Order::default()
            };
            let blob = seal::seal(&key, &ns, bucket, mode, &order, &body, salt).unwrap();
            o.section(&format!("mode_{mode:02x}_bucket_{bucket}"));
            o.kv(
                "key_class",
                if mode == seal::MODE_EPOCH {
                    "epoch"
                } else {
                    "join"
                },
            );
            o.hex(
                "key",
                if mode == seal::MODE_EPOCH {
                    k_ep.as_bytes()
                } else {
                    jk.as_bytes()
                },
            );
            o.hex("ns", &ns);
            o.kv("bucket", bucket.to_string());
            o.kv("mode", format!("{mode:02x}"));
            o.hex("salt", &salt);
            o.hex("order", &order.encode());
            o.hex("body", &body);
            o.hex("hint", &blob[16..32]);
            if bucket == 4096 {
                o.hex("blob", &blob);
            }
            o.hex("blob_sha256", &Sha256::digest(&blob));
            if mode != seal::MODE_EPOCH {
                // The joins open without MLS: the mutations are replayed.
                assert!(seal::open(&key, &ns, mode, &blob).is_ok());
                o.kv(
                    "refused",
                    "flip_byte_40,flip_byte_20,truncate_1,other_ns,other_mode",
                );
            }
        }
    }
    // A body at capacity and one byte over it.
    o.section("capacity");
    for b in seal::BUCKETS {
        o.kv(&format!("c_{b}"), seal::capacity(b).to_string());
    }
    o.kv(
        "bucket_small_4028",
        seal::bucket(4028, 0).unwrap().to_string(),
    );
    o.kv(
        "bucket_small_4029",
        seal::bucket(4029, 0).unwrap().to_string(),
    );
    o.kv("bucket_large_1", seal::bucket(1, 1).unwrap().to_string());
    o.kv("no_fit", "65469");
    o.section("ttl");
    for c in 0..=5u8 {
        o.kv(
            &format!("timer_{c}"),
            format!(
                "post={} handshake={} deadline={}",
                seal::post_ttl(c).unwrap(),
                seal::handshake_ttl(c).unwrap(),
                seal::op_deadline(c, false).unwrap()
            ),
        );
    }
    o.finish();
}

#[test]
fn ch_content() {
    let mut o = Out::new(
        "ch_content.txt",
        "GHOST ChannelContent v1 (design §5.5). Generated and checked by\n\
         client-core/mls/tests/vectors.rs::ch_content; replayed by client-core/mls-kat/tests/spec_replay.rs.\n\
         [ok_*] decode to the fields given and re-encode to the same bytes; [bad_*] are NON_CANONICAL.",
    );
    let base = |kind: u8, body: Body| ChannelContent {
        kind,
        op_id: b16("vector op"),
        author_minute: 29_000_000,
        timer_code: 4,
        body,
    };
    let cases: Vec<(&str, ChannelContent)> = vec![
        (
            "ok_post",
            base(
                1,
                Body::Post {
                    text: "hello, channel".into(),
                    reply_to: None,
                },
            ),
        ),
        (
            "ok_post_reply",
            base(
                1,
                Body::Post {
                    text: "ă UTF-8 reply".into(),
                    reply_to: Some(b16("parent")),
                },
            ),
        ),
        (
            "ok_reaction",
            base(
                2,
                Body::Reaction {
                    target: b16("target"),
                    grapheme: "👍".into(),
                },
            ),
        ),
        (
            "ok_reaction_withdrawn",
            base(
                2,
                Body::Reaction {
                    target: b16("target"),
                    grapheme: String::new(),
                },
            ),
        ),
        (
            "ok_invite_issued_open",
            base(
                3,
                Body::InviteIssued(InviteIssued {
                    invite_id: b16("invite id"),
                    invite_pk: b32("invite pk"),
                    expiry_day: 20_732,
                    sponsor_sig: [0x5c; 64],
                    committers_digest: b32("digest"),
                    pw_version: None,
                }),
            ),
        ),
        (
            "ok_invite_issued_password",
            base(
                3,
                Body::InviteIssued(InviteIssued {
                    invite_id: b16("invite id"),
                    invite_pk: b32("invite pk"),
                    expiry_day: 20_732,
                    sponsor_sig: [0x5c; 64],
                    committers_digest: b32("digest"),
                    pw_version: Some(2),
                }),
            ),
        ),
        ("ok_leave", base(4, Body::Leave)),
        (
            "ok_reveal",
            base(
                5,
                Body::Reveal {
                    hpke_enc: b32("enc"),
                    ciphertext: vec![0xa5; 40],
                },
            ),
        ),
    ];
    for (name, c) in &cases {
        let e = c.encode().unwrap();
        assert_eq!(&ChannelContent::decode(&e).unwrap(), c);
        o.section(name);
        o.hex("bytes", &e);
        o.kv("kind", c.kind.to_string());
        o.hex("op_id", &c.op_id);
        o.kv("author_minute", c.author_minute.to_string());
        o.kv("timer_code", c.timer_code.to_string());
        match &c.body {
            Body::Post { text, reply_to } => {
                o.hex("text", text.as_bytes());
                o.kv("reply_to", reply_to.map_or("-".into(), hex::encode));
            }
            Body::Reaction { target, grapheme } => {
                o.hex("target", target);
                o.hex("grapheme", grapheme.as_bytes());
            }
            Body::InviteIssued(i) => {
                o.hex("invite_id", &i.invite_id);
                o.hex("invite_pk", &i.invite_pk);
                o.kv("expiry_day", i.expiry_day.to_string());
                o.hex("sponsor_sig", &i.sponsor_sig);
                o.hex("committers_digest", &i.committers_digest);
                o.kv(
                    "pw_version",
                    i.pw_version.map_or("-".into(), |v| v.to_string()),
                );
            }
            Body::Leave => {}
            Body::Reveal {
                hpke_enc,
                ciphertext,
            } => {
                o.hex("hpke_enc", hpke_enc);
                o.hex("ciphertext", ciphertext);
            }
        }
    }
    let good = cases[0].1.encode().unwrap();
    let hdr = good[..23].to_vec();
    let tlv = |t: u16, v: &[u8]| -> Vec<u8> {
        let mut x = t.to_be_bytes().to_vec();
        x.extend_from_slice(&(v.len() as u16).to_be_bytes());
        x.extend_from_slice(v);
        x
    };
    let with = |kind: u8, parts: &[Vec<u8>]| -> Vec<u8> {
        let mut b = hdr.clone();
        b[1] = kind;
        for p in parts {
            b.extend_from_slice(p);
        }
        b
    };
    let bad: Vec<(&str, Vec<u8>)> = vec![
        ("bad_trailing_byte", [good.clone(), vec![0]].concat()),
        ("bad_version_2", {
            let mut b = good.clone();
            b[0] = 2;
            b
        }),
        ("bad_timer_6", {
            let mut b = good.clone();
            b[22] = 6;
            b
        }),
        (
            "bad_kind_flag",
            with(6, &[tlv(0x0030, &[1; 32]), tlv(0x0031, &[1])]),
        ),
        ("bad_kind_pin", with(7, &[])),
        ("bad_tlv_order", with(1, &[tlv(2, &[0; 16]), tlv(1, b"x")])),
        ("bad_tlv_duplicate", with(1, &[tlv(1, b"x"), tlv(1, b"y")])),
        (
            "bad_media_ref_before_slice",
            with(1, &[tlv(1, b"x"), tlv(3, &[0; 84])]),
        ),
        ("bad_post_without_text", with(1, &[])),
        ("bad_post_empty_text", with(1, &[tlv(1, b"")])),
        ("bad_post_invalid_utf8", with(1, &[tlv(1, &[0xc3, 0x28])])),
        (
            "bad_post_text_16001",
            with(1, &[tlv(1, &vec![b'a'; 16_001])]),
        ),
        (
            "bad_reply_to_15",
            with(1, &[tlv(1, b"x"), tlv(2, &[0; 15])]),
        ),
        (
            "bad_reaction_grapheme_33",
            with(2, &[tlv(4, &[0; 16]), tlv(5, &[b'a'; 33])]),
        ),
        ("bad_unlisted_tlv_in_leave", with(4, &[tlv(1, b"x")])),
        (
            "bad_invite_pw_version_0",
            with(
                3,
                &[
                    tlv(0x10, &[1; 16]),
                    tlv(0x11, &[1; 32]),
                    tlv(0x12, &[0, 0, 0x51, 0]),
                    tlv(0x13, &[1; 64]),
                    tlv(0x14, &[1; 32]),
                    tlv(0x15, &[0, 0]),
                ],
            ),
        ),
        (
            "bad_reveal_ct_513",
            with(5, &[tlv(0x20, &[0; 32]), tlv(0x21, &[0; 513])]),
        ),
    ];
    for (name, b) in &bad {
        assert!(ChannelContent::decode(b).is_err(), "{name}");
        o.section(name);
        if b.len() > 1024 {
            // Long cases by recipe: the header of ok_post, kind byte and one TLV given by length.
            o.kv(
                "recipe",
                format!(
                    "ok_post header, kind 1, tlv 0x0001 of {} bytes 0x61",
                    b.len() - 23 - 4
                ),
            );
        } else {
            o.hex("bytes", b);
        }
    }
    o.section("sizes");
    let longest = base(
        1,
        Body::Post {
            text: "a".repeat(16_000),
            reply_to: None,
        },
    );
    o.kv(
        "longest_text_post_content",
        longest.encode().unwrap().len().to_string(),
    );
    o.finish();
}

#[test]
fn ch_invite() {
    let mut o = Out::new(
        "ch_invite.txt",
        "GHOST ChannelInviteV2 (design §5.9, §19.28.3 corrected by §19.29.3). Generated and checked by\n\
         client-core/mls/tests/vectors.rs::ch_invite; replayed by client-core/mls-kat/tests/spec_replay.rs.\n\
         Every invite is 335 bytes; the link is ghost://channel/ + base32 (lowercase, unpadded), 552 characters.\n\
         kdf_code 1 = Argon2id m=65536 KiB t=1 p=4 (RFC 9106), ikm = Argon2id(password, salt); kdf_code 0: ikm = salt.",
    );
    let fields = |name_len: usize| InviteFields {
        suite: 3,
        size_class: 0,
        handshake_ttl_code: 4,
        channel_id: b32("vector channel"),
        generation: 2,
        ns: b32("vector ns"),
        read_base: ReadBase::from_bytes(b32("vector read base")),
        deposit_base: DepositBase::from_bytes(b32("vector deposit base")),
        join_key: JoinKey::from_bytes(b32("vector join key")),
        invite_id: b16("vector invite id"),
        invite_seed: InviteSeed::from_bytes(b32("vector invite seed")),
        committers_digest: b32("vector digest"),
        expiry_day: 20_732,
        name: vec![b'n'; name_len],
    };
    let pw = InvitePassword::from_bytes(b"cabin frost ladder margin orbit".to_vec());
    for (name, kdf, name_len) in [
        ("open_name_0", 0u8, 0usize),
        ("open_name_48", 0, 48),
        ("password_name_0", 1, 0),
        ("password_name_48", 1, 48),
    ] {
        let f = fields(name_len);
        let salt = b16(&format!("vector invite salt {name}"));
        let bytes = invite::build_v2(&f, kdf, (kdf == 1).then_some(&pw), salt).unwrap();
        assert_eq!(bytes.len(), 335);
        o.section(name);
        o.kv("kdf_code", kdf.to_string());
        if kdf == 1 {
            o.hex("password", pw.as_bytes());
        }
        o.hex("salt", &salt);
        o.hex("suite", &f.suite.to_be_bytes());
        o.kv("size_class", f.size_class.to_string());
        o.kv("handshake_ttl_code", f.handshake_ttl_code.to_string());
        o.hex("channel_id", &f.channel_id);
        o.kv("generation", f.generation.to_string());
        o.hex("ns", &f.ns);
        o.hex("read_base", f.read_base.as_bytes());
        o.hex("deposit_base", f.deposit_base.as_bytes());
        o.hex("join_key", f.join_key.as_bytes());
        o.hex("invite_id", &f.invite_id);
        o.hex("invite_seed", f.invite_seed.as_bytes());
        o.hex("committers_digest", &f.committers_digest);
        o.kv("expiry_day", f.expiry_day.to_string());
        o.hex("name", &f.name);
        o.hex("invite", &bytes);
        o.kv("link", invite::to_link(&bytes));
        o.hex("invite_pk", &f.invite_pk());
    }
    o.section("refusals");
    o.kv("wrong_password", "cabin frost ladder margin orbit.");
    o.kv("expect", "password_name_0: no password -> PASSWORD_REQUIRED; wrong password -> WRONG_PASSWORD; flip_byte_40 -> WRONG_PASSWORD; kdf_code byte 1 -> 0 -> WRONG_PASSWORD; version byte 0 -> 1 -> NON_CANONICAL; kdf_code 2 -> NON_CANONICAL; truncate_1 -> NON_CANONICAL");
    o.kv(
        "link_characters",
        (16 + base32_lower(&[0u8; 335]).len()).to_string(),
    );
    o.finish();
}

#[test]
fn ch_join() {
    let mut o = Out::new(
        "ch_join.txt",
        "GHOST join traffic and extension formats (design §5.3, §5.4, §5.5, §5.6, §19.2, §19.3).\n\
         Generated and checked by client-core/mls/tests/vectors.rs::ch_join; replayed by\n\
         client-core/mls-kat/tests/spec_replay.rs. [key_package] is a sample canonical KeyPackage\n\
         (MLS randomness: made once, then re-checked); every signature below is Ed25519 over it.",
    );
    let prev = committed("ch_join.txt");
    let ch = b32("vector channel");
    let ps = PseudonymSeed::from_bytes(b32("vector pseudonym seed"));
    let kp_bytes = if writing() || !prev.contains_key("key_package") {
        let ctx = MlsContext::open(StateKey::from_bytes(b32("vector state"))).unwrap();
        let h = ChannelHandle::open(ch, &ps);
        ctx.key_package(&h, Purpose::Join, 20_725)
            .unwrap()
            .key_package
    } else {
        hex::decode(&prev["key_package"]["bytes"]).unwrap()
    };
    let crypto = openmls_libcrux_crypto::CryptoProvider::new().unwrap();
    let parsed = canonical::parse_key_package(&crypto, &kp_bytes, Some(&ch)).unwrap();
    assert_eq!(kp_bytes.len(), 395);
    o.section("key_package");
    o.hex("bytes", &kp_bytes);
    o.kv("length", kp_bytes.len().to_string());
    o.hex("kp_ref", &parsed.kp_ref);
    o.hex("pseudonym_key", &parsed.pseudonym);
    o.hex("box_pk", &parsed.box_pk);
    o.hex("kp_bind", &parsed.bind.encode());
    o.hex("sha256", &Sha256::digest(&kp_bytes));

    let seed = InviteSeed::from_bytes(b32("vector invite seed"));
    let ik = derive_invite_signing_key(&seed);
    let invite_id = b16("vector invite id");
    let msg = join::invite_sig_message(&ch, &invite_id, &kp_bytes);
    let invite_sig = invite::sign_sponsor(&ik, &msg);
    let jr = JoinRequest {
        request_type: RequestType::Join,
        key_package: kp_bytes.clone(),
        auth: JoinAuth::Invite {
            invite_id,
            invite_sig,
        },
    }
    .encode()
    .unwrap();
    o.section("join_request");
    o.hex("channel_id", &ch);
    o.hex("invite_seed", seed.as_bytes());
    o.hex("invite_id", &invite_id);
    o.hex("invite_sig_message", &msg);
    o.hex("invite_sig", &invite_sig);
    o.hex("body", &jr);

    let pk = SigningKey::from_bytes(ps.as_bytes());
    let (generation, day, last_epoch, last_hash) =
        (3u32, 20_726u32, 41u64, b32("vector last hash"));
    let rmsg = join::rejoin_sig_message(&ch, generation, day, last_epoch, &last_hash, &kp_bytes);
    let rejoin_sig = invite::sign_sponsor(&pk, &rmsg);
    let rj = JoinRequest {
        request_type: RequestType::Rejoin,
        key_package: kp_bytes.clone(),
        auth: JoinAuth::Rejoin {
            day,
            last_epoch,
            last_hash,
            rejoin_sig,
        },
    }
    .encode()
    .unwrap();
    o.section("rejoin_request");
    o.hex("pseudonym_seed", ps.as_bytes());
    o.kv("generation", generation.to_string());
    o.kv("day", day.to_string());
    o.kv("last_epoch", last_epoch.to_string());
    o.hex("last_hash", &last_hash);
    o.hex("rejoin_sig_message", &rmsg);
    o.hex("rejoin_sig", &rejoin_sig);
    o.hex("body", &rj);

    let sponsor = SigningKey::from_bytes(&b32("vector sponsor seed"));
    let smsg = invite::sponsor_message(&ch, &invite_id, &ik.verifying_key().to_bytes(), 20_732);
    o.section("sponsor_sig");
    o.hex("sponsor_seed", &b32("vector sponsor seed"));
    o.hex("sponsor_key", &sponsor.verifying_key().to_bytes());
    o.hex("invite_pk", &ik.verifying_key().to_bytes());
    o.kv("expiry_day", "20732");
    o.hex("message", &smsg);
    o.hex("sponsor_sig", &invite::sign_sponsor(&sponsor, &smsg));

    let wb = WelcomeBlob {
        kp_ref: parsed.kp_ref.clone(),
        welcome: b"welcome bytes (opaque here)".to_vec(),
    }
    .encode()
    .unwrap();
    o.section("welcome_blob");
    o.hex("kp_ref", &parsed.kp_ref);
    o.hex("welcome", b"welcome bytes (opaque here)");
    o.hex("bytes", &wb);

    let keys: Vec<[u8; 32]> = (0..8)
        .map(|i| b32(&format!("vector committer {i}")))
        .collect();
    let ctx_max = ChannelContext {
        channel_id: ch,
        size_class: 1,
        timer_code: 5,
        timer_version: 513,
        history_policy: 0,
        flags: 0b100,
        idle_evict_days: 70,
        pw_version: 3,
        name: vec![b'a'; 48],
        committers: keys.clone(),
        funders: keys[..3].to_vec(),
    };
    let ctx_min = ChannelContext {
        channel_id: ch,
        size_class: 0,
        timer_code: 4,
        timer_version: 0,
        history_policy: 0,
        flags: 1,
        idle_evict_days: 63,
        pw_version: 0,
        name: vec![],
        committers: keys[..1].to_vec(),
        funders: keys[..1].to_vec(),
    };
    o.section("channel_context");
    o.hex("max", &ctx_max.encode());
    o.kv("max_length", ctx_max.encode().len().to_string());
    o.hex("initial", &ctx_min.encode());
    o.section("ghost_leaf");
    o.hex(
        "bytes",
        &GhostLeaf {
            box_pk: b32("box"),
            refresh_epoch: 9,
        }
        .encode(),
    );
    o.section("kp_bind");
    o.hex(
        "bytes",
        &KpBind {
            channel_id: ch,
            purpose: Purpose::Restore,
            day: 20_725,
        }
        .encode(),
    );
    o.section("bootstrap");
    o.hex(
        "bytes",
        &Bootstrap {
            generation: 2,
            open_epoch: 17,
            g: b32("vector G"),
        }
        .encode(),
    );
    o.section("channel_order");
    o.hex(
        "bytes",
        &ChannelOrder {
            sender_leaf: 3,
            seq: 12,
        }
        .encode(),
    );
    let admit = AdmitEvidence {
        kp_ref: parsed.kp_ref.clone(),
        invite_id,
        invite_pk: ik.verifying_key().to_bytes(),
        expiry_day: 20_732,
        sponsor: sponsor.verifying_key().to_bytes(),
        sponsor_sig: invite::sign_sponsor(&sponsor, &smsg),
        invite_sig,
    };
    let aad = CommitAad {
        commit_minute: 29_844_000,
        rotate: true,
        admits: vec![admit.clone()],
        swaps: vec![
            SwapEvidence::Rejoin {
                kp_ref: parsed.kp_ref.clone(),
                generation,
                day,
                last_epoch,
                last_hash,
                rejoin_sig,
            },
            SwapEvidence::Restore(admit),
        ],
    };
    o.section("commit_aad");
    o.hex("bytes", &aad.encode());
    o.hex("empty", &CommitAad::default().encode());
    o.finish();
}
